SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='597dd25a-072f-5fce-b142-055e2980edfb'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('3efa9fb9-fe44-5c82-85c4-a56fc1ec7449','beabe250-cf41-5824-b8dd-12db195c3d92')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='597dd25a-072f-5fce-b142-055e2980edfb'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='597dd25a-072f-5fce-b142-055e2980edfb'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('3efa9fb9-fe44-5c82-85c4-a56fc1ec7449','beabe250-cf41-5824-b8dd-12db195c3d92')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='597dd25a-072f-5fce-b142-055e2980edfb'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
