  AND q.result_body='{"contract":"SH-004.v1","requestId":"unique-race-different-subjects-identical-text-key-a","status":"ok","value":{"customerProfileId":"597dd25a-072f-5fce-b142-055e2980edfb","userId":"c15db2cb-2508-55b4-bff6-040aa84486bc","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"3efa9fb9-fe44-5c82-85c4-a56fc1ec7449","semanticKey":"unique-control-different-subjects-identical-text-key","fingerprint":"b5b980f8182c054e1a44ddc353d2bb164cd23222d26068e53108ea7bbadb38a7","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='957c7d98-8935-53fe-917b-821f9cf0382a' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='3a836053-d23e-5f2e-a0c8-d974340c9fab' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"597dd25a-072f-5fce-b142-055e2980edfb"},"prior":null,"committed":{"id":"597dd25a-072f-5fce-b142-055e2980edfb","userId":"c15db2cb-2508-55b4-bff6-040aa84486bc","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='597dd25a-072f-5fce-b142-055e2980edfb' AND c.user_id='c15db2cb-2508-55b4-bff6-040aa84486bc' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
