    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"c15db2cb-2508-55b4-bff6-040aa84486bc","track":"customer","customerProfileId":"597dd25a-072f-5fce-b142-055e2980edfb","sourceCreationRevision":"0","sourceCreationReceipt":"3efa9fb9-fe44-5c82-85c4-a56fc1ec7449","semanticKey":"customer_buyer_profile/597dd25a-072f-5fce-b142-055e2980edfb/default-free-enrollment/v1"}'::jsonb)))=2));
